mapper.select:
select *, b.name as classifyName from drive_device a
left join sys_classify b on a.classify = b.code


        and drive_id = #{driveId}


        and classify = #{classify}


        and manufacturer = #{manufacturer}


        and a.`name` in

            #{item}

SELECT
    (select count(0) from drive_device where 1= 1
         and classify = #{classify} 
    ) as totalNum,
    (select count(0) from drive_device where status ='online'
         and classify = #{classify} 
    ) as onlineNum,
    (select count(0) from drive_device where status ='offline'
         and classify = #{classify} 
    ) as offlineNum,
    (SELECT ROUND(SUM(TIMESTAMPDIFF(SECOND, offline_time, NOW()) / 3600), 2) AS total_offline_hours
        FROM drive_device WHERE offline_time IS NOT NULL
         and classify = #{classify} 
    ) as offTime

select a.*, b.url
from drive_device a
left join drive_info b on a.drive_id = b.id
where b.`status` = 'install_success'

    and a.classify = #{classify}


    and a.manufacturer = #{manufacturer}
